const here = position();
if (inventory_count('wheat_seeds') < 1) {
  const grass = find_block({ names: ['tall_grass', 'short_grass'], max_distance: 16 });
  if (!grass) {
    return { done: false, detail: 'no grass to gather seeds from' };
  }
  const pulled = await dig(grass.x, grass.y, grass.z);
  if (!pulled.ok) {
    return { done: false, detail: pulled.detail };
  }
}
if (inventory_count('wheat_seeds') < 1) {
  return { done: false, detail: 'no seeds to plant' };
}
const put = await place('wheat_seeds', here.x + 1, here.y, here.z);
if (!put.ok) {
  return { done: false, detail: put.detail };
}
return { done: true, detail: 'planted seeds' };
